/* Elegant Luxury Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="elegant-luxury-light"] {
  --background: hsl(300 0% 97.37%);
  --foreground: hsl(300 0% 10.4%);
  --card: hsl(300 0% 97.37%);
  --card-foreground: hsl(300 0% 10.4%);
  --popover: hsl(300 0% 97.37%);
  --popover-foreground: hsl(300 0% 10.4%);
  --primary: hsl(359.86 56.4% 39.56%);
  --primary-foreground: hsl(300 50% 100%);
  --secondary: hsl(43.07 89.28% 91.09%);
  --secondary-foreground: hsl(39.52 95.27% 25.29%);
  --muted: hsl(22.52 29.45% 92.14%);
  --muted-foreground: hsl(33.34 5.76% 31.86%);
  --accent: hsl(47.99 95.85% 88.35%);
  --accent-foreground: hsl(0.55 60.45% 31.1%);
  --destructive: hsl(360 70.13% 34.87%);
  --destructive-foreground: hsl(300 50% 100%);
  --border: hsl(37.71 63.48% 89.98%);
  --input: hsl(37.71 63.48% 89.98%);
  --ring: hsl(359.86 56.4% 39.56%);
  --chart-1: hsl(0.35 72.36% 42.42%);
  --chart-2: hsl(359.86 56.4% 39.56%);
  --chart-3: hsl(0.55 60.45% 31.1%);
  --chart-4: hsl(27.04 99.37% 36.06%);
